using System.IO;
using System.Text.Json;

namespace MapEditor.Map;

/// Metadata for the burnt-forest volcanic crater generated by WorldGenerator and stored as yamee_volcano.json.
/// Carries the NeedsWildernessPois flag so WildernessGenerator places two medium POIs on the prepared pads
/// (one on the crater rim, one halfway up), connects them with a 5 m gravel road along the wrapping spiral,
/// and applies 1–2 landslides to the finished road.
public sealed class VolcanoSite
{
    public const string FileName = "yamee_volcano.json";

    public double CenterX { get; set; }
    public double CenterZ { get; set; }
    public double OuterRadius { get; set; }
    public double RimRadius { get; set; }
    public double RimHeight { get; set; }
    public double FloorHeight { get; set; }
    public bool HasLake { get; set; }
    public int LakeLevel { get; set; }
    public bool NeedsWildernessPois { get; set; } = true;
    /// Arc distance (m) along AccessPath where the flat landing podest for Pad 1 (mid-height POI) sits.
    public double PodestDist { get; set; }

    public List<VolcanoPad> Pads { get; set; } = new();
    /// Ramp centerline from the rim arrival near Pad 0 down to the outer foot of the volcano (world coordinates).
    public List<VolcanoPoint> AccessPath { get; set; } = new();
    /// Branch centerline connecting Pad 1 (mid-height) to the wrapping spiral road (world coordinates).
    public List<VolcanoPoint> RimConnector { get; set; } = new();
    /// 1–2 landslides along the spiral road (either slumped downhill or buried by debris from uphill).
    public List<VolcanoLandslide> Landslides { get; set; } = new();

    static readonly JsonSerializerOptions JsonOpts = new() { WriteIndented = true };

    public void Save(string folder)
    {
        if (string.IsNullOrEmpty(folder)) return;
        File.WriteAllText(Path.Combine(folder, FileName), JsonSerializer.Serialize(this, JsonOpts));
    }

    public static VolcanoSite Load(string folder)
    {
        if (string.IsNullOrEmpty(folder)) return null;
        string path = Path.Combine(folder, FileName);
        if (!File.Exists(path)) return null;
        try { return JsonSerializer.Deserialize<VolcanoSite>(File.ReadAllText(path)); }
        catch (Exception) { return null; }
    }
}

public sealed class VolcanoPad
{
    public double X { get; set; }
    public double Z { get; set; }
    public double Radius { get; set; }
    public double Height { get; set; }
    /// Preferred building exit direction (radians, atan2(dz, dx)) facing toward the prepared 5 m gravel road.
    public double ExitAngle { get; set; }
}

public sealed class VolcanoPoint
{
    public double X { get; set; }
    public double Z { get; set; }
    /// Prepared target elevation along the volcano spiral (m); null on legacy files.
    public double? H { get; set; }

    public VolcanoPoint() { }
    public VolcanoPoint(double x, double z, double? h = null) { X = x; Z = z; H = h; }
}

public sealed class VolcanoLandslide
{
    public double X { get; set; }
    public double Z { get; set; }
    /// Unit vector along the road centerline.
    public double DirX { get; set; }
    public double DirZ { get; set; }
    /// Unit vector pointing downhill (perpendicular to road, away from the volcano slope).
    public double DownX { get; set; }
    public double DownZ { get; set; }
    /// Extent along the road (m).
    public double Length { get; set; }
    /// Vertical displacement strength (m).
    public double Strength { get; set; }
    /// true = debris tongue from uphill buries the road; false = downhill slump drops/breaks the road edge.
    public bool BuryFromAbove { get; set; }
    public int Seed { get; set; }
}
